java.solutionCode:
class Solution {
  public int PopulationByContinent(Country[] countries, String continent) {
    return Arrays.stream(countries)
        .filter(country -> country.GetContinent().equals(continent))
        .mapToInt(country -> country.GetPopulation())
        .sum();
  }
}
